cd /tmp/bni_personalize && python3 << 'EOF'
import re

files = ["bni-invite.html", "bni-peipei.html", "workshop-invite.html", "workshop-peipei.html"]

greet_html = '\n    <p class="personal-greet" id="personalGreet" style="display:none;font-size:18px;color:var(--orange-soft);font-weight:800;margin:10px 0 -6px;letter-spacing:1px;"></p>'

script_html = '''
<script>
(function(){
  var params = new URLSearchParams(window.location.search);
  var name = params.get('name');
  if (name) {
    var el = document.getElementById('personalGreet');
    if (el) {
      el.textContent = decodeURIComponent(name) + ' 您好';
      el.style.display = 'block';
    }
  }
})();
</script>
'''

for f in files:
    with open(f, encoding='utf-8') as fh:
        content = fh.read()
    # insert greet_html right after the FIRST eyebrow span (hero section)
    idx = content.find('<span class="eyebrow">')
    end_idx = content.find('</span>', idx) + len('</span>')
    content = content[:end_idx] + greet_html + content[end_idx:]
    # insert script before </body>
    content = content.replace('</body>', script_html + '</body>')
    with open(f, 'w', encoding='utf-8') as fh:
        fh.write(content)
    print(f, "done")
EOF
grep -n "personalGreet" bni-invite.html

cd /tmp/bni_personalize && python3 << 'EOF'
import re

files = ["bni-invite.html", "bni-peipei.html", "workshop-invite.html", "workshop-peipei.html"]

old_greet_line = '\n    <p class="personal-greet" id="personalGreet" style="display:none;font-size:18px;color:var(--orange-soft);font-weight:800;margin:10px 0 -6px;letter-spacing:1px;"></p>'

old_script = '''
<script>
(function(){
  var params = new URLSearchParams(window.location.search);
  var name = params.get('name');
  if (name) {
    var el = document.getElementById('personalGreet');
    if (el) {
      el.textContent = decodeURIComponent(name) + ' 您好';
      el.style.display = 'block';
    }
  }
})();
</script>
'''

new_script = '''
<script>
(function(){
  var params = new URLSearchParams(window.location.search);
  var name = params.get('name');
  if (name) {
    var eyebrow = document.querySelector('.hero .eyebrow');
    if (eyebrow) {
      var t = eyebrow.textContent;
      if (t.indexOf('BNI') !== -1) {
        eyebrow.textContent = t.replace('BNI', name);
      } else if (t.indexOf('工作坊') !== -1) {
        eyebrow.textContent = t.replace('工作坊', name);
      }
    }
  }
})();
</script>
'''

for f in files:
    with open(f, encoding='utf-8') as fh:
        content = fh.read()
    assert old_greet_line in content, f"greet line not found in {f}"
    assert old_script in content, f"script not found in {f}"
    content = content.replace(old_greet_line, '')
    content = content.replace(old_script, new_script)
    with open(f, 'w', encoding='utf-8') as fh:
        fh.write(content)
    print(f, "updated")
EOF
